// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 newVal) internal {
        uint256 minSumBefore;
        try c.MinSum() returns (uint256 __r) { minSumBefore = __r; } catch { return; }
        bool reverted;
        try c.SetMinSum(newVal) { reverted = false; } catch { reverted = true; }
        uint256 minSumAfter;
        try c.MinSum() returns (uint256 __r) { minSumAfter = __r; } catch { return; }
        assertTrue(reverted ? minSumAfter == minSumBefore : minSumAfter == newVal);
    }

    function testFuzz_run(uint256 newVal) public {
        _run(newVal);
    }

    receive() external payable {}
}
